-- Ownership achievements: retain usable vendor/quest details from the mount
-- guides and correct achievement comments that still quote retired currencies.
local _, TDP = ...
local guides=TDP.CollectionWalkthroughs.achievements
local function pin(mapID,x,y,step,label)
    return {mapID=mapID,x=x/100,y=y/100,step=step,label=label}
end
local function add(id,name,steps,waypoints,tips,comments)
    local lines,sources={},{}
    for i,s in ipairs(steps) do lines[i]=i..". "..s end
    for _,c in ipairs(comments or {}) do sources[#sources+1]=type(c)=="number" and ("https://www.wowhead.com/achievement="..id.."#comments:id="..c) or c end
    guides[id]={achievementId=id,name=name,category="Collections",sourceType="Achievement",source=name,
        acquisition=table.concat(lines,"\n\n"),stepCount=#steps,waypoints=waypoints,tips=tips,sources=sources,
        wowheadUrl="https://www.wowhead.com/achievement="..id,sourceURL="https://www.wowhead.com/achievement="..id.."#comments"}
end
for _,a in ipairs({{2076,"Armored Brown Bear",750,60114,60116},{2077,"Wooly Mammoth",10000,59791,59793},{2078,"Traveler's Tundra Mammoth",20000,61425,61447}}) do
    add(a[1],a[2],{
        "Travel to the ORIGINAL Dalaran above Crystalsong Forest in Northrend and find Mei Francis outdoors at 57.8, 42.5, near the Horde-quarter entrance. She is the exotic-mount vendor, not Breanni inside the nearby pet shop.",
        "Bring "..a[3].." gold to cover "..a[2].."'s base price. No Kirin Tor reputation rank is required to buy it; your current reputation can lower the displayed gold price. An Exalted discount normally reduces it to "..(a[3]*0.8).." gold.",
        "Buy the reins for your faction and USE them from your bags, then check the achievement and Mount Journal. "..(a[1]==2077 and "Retail Wooly Mammoth is a GOLD purchase; old Emblem of Heroism and Justice Point costs are obsolete." or a[1]==2076 and "Do not confuse this brown bear with the different Black War Bear from faction-leader kills." or "This is the mammoth with repair/trade NPCs. Grand Ice/Grand Black War Mammoths have passengers but no vendors."),
        "If this mount is already learned, check existing account achievement credit before buying another copy. The journal handles eligible faction counterparts; an unrelated same-color bear/mammoth does not substitute.",
    },{pin(125,57.8,42.5,1,"Mei Francis - Northrend Dalaran"),pin(125,57.8,42.5,3,"Buy and learn "..a[2])},nil,{ "https://www.wowhead.com/achievement="..a[1].."#comments","https://www.wowhead.com/spell="..a[4],"https://www.wowhead.com/spell="..a[5]})
end
add(2080,"Black War Mammoth",{
    "Collect FIFTEEN Marks of Honor items from PvP reward sources. Honor points, old Wintergrasp Marks and Stone Keeper's Shards are different resources; the original achievement comments quote superseded prices.",
    "Travel to OUTDOOR Wintergrasp in Northrend and check which faction controls the fortress. Visit its courtyard quartermaster near 51.7, 17.2 when friendly: Knight Dameron for Alliance or Stone Guard Mukar for Horde.",
    "Buy Reins of the Black War Mammoth for 15 Marks of Honor and use the reins. If the opposing faction controls this outdoor copy, return later or use an eligible character for its faction counterpart.",
    "Check the achievement and mount collection. This is the single-rider vendor mount, not the Grand Black War Mammoth raid drop. Killing Vault bosses is unnecessary for this particular mammoth.",
},{pin(123,51.7,17.2,2,"Outdoor Wintergrasp - friendly fortress quartermaster"),pin(123,51.7,17.2,3,"Dameron / Mukar - 15 Marks of Honor")},nil,{1873763,"https://www.wowhead.com/item=44077#comments:id=5236050"})
add(2081,"Grand Black War Mammoth",{
    "Travel to outdoor Wintergrasp when your faction controls the fortress. Set your legacy raid size outside and enter the Vault of Archavon portal at the back of the fortress (50.0, 11.9). The Epic Battleground queue leads to a separate battle instance.",
    "Kill and loot ALL FOUR bosses: Archavon, Emalon, Koralon and Toravon. Any of them can drop the reins, in either legacy raid size. You do not need a Hard Mode, timed achievement or special four-boss kill order.",
    "If Reins of the Grand Black War Mammoth drops, loot it and use the faction-appropriate item to learn the mount and check the achievement. The cheaper 15-Mark vendor Black War Mammoth is a separate item.",
    "If no reins drop, use another eligible character or return after the relevant weekly lockout. Check your Raid Info before trying another size; an already saved boss does not give another roll from resetting the instance.",
},{pin(123,50,11.9,1,"Vault of Archavon - OUTDOOR fortress portal"),pin(156,49.3,16.8,2,"Archavon - loot for mammoth chance"),pin(156,62.7,55.3,2,"Emalon - loot for mammoth chance"),pin(156,36.3,55.1,2,"Koralon - loot for mammoth chance"),pin(156,62.7,36.3,2,"Toravon - loot for mammoth chance")},"This obtainable Feat of Strength was removed from Master of Wintergrasp's requirements because the drop is rare. Its old anniversary-event source is not presented as a permanent route.",{633148,693651,"https://www.wowhead.com/item=44083#comments:id=626536","https://www.wowhead.com/item=43959#comments:id=589210"})
for _,grand in ipairs({false,true}) do
    local id=grand and 2083 or 2082
    local name=grand and "Grand Ice Mammoth" or "Ice Mammoth"
    add(id,name,{
        "If the Sons of Hodir are hostile, start They Took Our Men! with Gretchen Fizzlespark in K3 (41.1, 86.1). Follow the Brunnhildar, bear, drake and Thorim introduction through Sibling Rivalry and Mending Fences. Enable Trivial Quests.",
        "During Mending Fences, loot Slag Covered Metal and complete The Refiner's Fire and A Spark of Hope. Follow the Thorim/Hodir yellow quests until Dun Niffelem is friendly and Lillehoff's reputation turn-ins/vendor are available.",
        "Raise Sons of Hodir to "..(grand and "EXALTED" or "REVERED").." through unlocked dailies and batches of Relics of Ulduar turned in to Lillehoff (66.1, 61.4). You can buy relics; check your actual bar before purchasing a large surplus.",
        "Buy Reins of the "..name.." from Lillehoff. The base price is "..(grand and "10,000" or "1,000").." gold before discounts, and he offers the appropriate faction item. "..(grand and "The required Exalted standing normally makes the price 8,000 gold." or "Revered normally makes it 850 gold; you do not need Exalted for the ordinary Ice Mammoth."),
        "Use the reins, confirm the achievement and check the mount collection. "..(grand and "This three-person mammoth has two party-passenger seats, with no repair/trade NPCs." or "This is the single-rider mammoth; the larger Grand Ice Mammoth is a separate Exalted purchase."),
    },{pin(120,41.1,86.1,1,"Gretchen - start Sons of Hodir unlock"),pin(120,66.1,61.4,3,"Lillehoff - Relics of Ulduar / reputation"),pin(120,66.1,61.4,4,"Lillehoff - buy "..name)},"Do not plan around the removed guild Bartering discount or assume the ordinary and Grand mammoths share a reputation requirement.",grand and {506934,875002,997833} or {506930,1356254})
end
add(2084,"Ring of the Kirin Tor",{
    "Go to Harold Winston inside the Cartier & Co. jewelry shop in ORIGINAL Northrend Dalaran (around 39.4, 34.8). Bring 8,500 gold to cover an original ring's base cost; Kirin Tor reputation discounts lower the displayed price, normally to 6,800 at Exalted.",
    "Buy one ORIGINAL qualifying variant: Signet of the Kirin Tor (40585), Band of the Kirin Tor (40586), Loop of the Kirin Tor (44934) or Ring of the Kirin Tor (44935). You do not need a later Inscribed/Etched/Runed upgrade or the much more expensive Empowered ring for this Wrath achievement.",
    "Check achievement credit after the purchase. If the game has not recorded it, equip your qualifying original ring when level-eligible and check again. Keep it if you want its independent Northrend Dalaran teleport.",
    "If considering a refund, inspect THIS item's current refund text before equipping, using, enchanting or altering it. Comment reports span different rings and patches and conflict; do not assume a gold refund or retained achievement is guaranteed. The normal buy-and-keep route needs no refund trick.",
},{pin(125,39.4,34.8,1,"Harold Winston - Cartier & Co. original rings"),pin(125,39.4,34.8,2,"Choose an original 8,500g-base ring variant")},"A Legion Dalaran hearthstone or a teleport from another item does not satisfy ownership of a listed original Kirin Tor ring. The 250,000-gold Empowered-ring comment refers to a different item.",{380655,1027848,3251737,6040545,6276258,"https://www.wowhead.com/npc=32172/harold-winston#sells"})
add(2097,"Get to the Choppa!",{
    "For the direct route, buy a completed Mekgineer's Chopper (Alliance) or Mechano-hog (Horde) from the Auction House or a crafter. The OWNER does not need Engineering. Use the finished mount item to learn it and check achievement credit; merely crafting one for sale or riding in a friend's sidecar is insufficient.",
    "For the crafting route, the crafter needs 75 Northrend Engineering and Exalted Alliance Vanguard (Alliance) or Horde Expedition (Horde), then buys and learns the matching schematic. The Winds of the North guide explains the default-reputation farm without a championing tabard.",
    "Supply twelve Titansteel Bars, forty Handfuls of Cobalt Bolts and two Arctic Fur. Compare material and finished-mount prices before committing to a craft; none of these quantities is a promise of an Auction House price.",
    "The qualified engineer buys the specialized parts from Roxi Ramrocket in K3, Storm Peaks (40.7, 84.8): one Salvaged Iron Golem Parts, eight Goblin-machined Pistons and one Elementium-plated Exhaust Pipe. Their base combined cost is 12,500 gold; a limited-stock part may require a later visit.",
    "Craft the faction's motorcycle at an anvil, trade it to its intended owner if necessary, and have that owner USE the finished item. Sending an unlearned motorcycle between characters is not a dependable achievement method. Keep the learned mount and invite a party passenger to use its sidecar.",
},{pin(120,40.7,84.8,4,"Roxi Ramrocket - qualified engineer's specialized parts"),pin(120,40.7,84.8,5,"K3 - craft at an anvil"),pin(114,57.6,66.4,2,"Alliance Vanguard - schematic quartermaster at Valiance Keep"),pin(114,41.4,53.6,2,"Horde Expedition - schematic quartermaster at Warsong Hold")},"An engineer can craft the tradeable motorcycle for another player. The intended owner must learn the finished mount; owning the schematic or components is insufficient.",{418656,425353,745922,870177,"https://www.wowhead.com/npc=31247/roxi-ramrocket"})
add(4596,"The Sword in the Skull",{
    "Obtain a Battered Hilt for YOUR faction: Alliance item 50379 or Horde item 50380, usable from level 25. Buy it from the Auction House or farm eligible Frozen Halls trash. Retail 2026 comments confirm drops from NORMAL Pit of Saron, including its first trash packs; this is a rare drop, not a guaranteed reward from a clear. Mailing a hilt to an opposite-faction character converts its faction version; moving it through the Warband bank does not.",
    "Use the hilt to start The Battered Hilt. Take it to Caladis Brightspear (Alliance, 74.2, 31.2) or Myralion Sunblaze (Horde, 74.4, 31.2) at Quel'Delar's Rest in Icecrown, south of the Argent Tournament. If a quest marker sends you to the Frozen Halls prematurely, check this outdoor camp first.",
    "Accept What The Dragons Know and speak to KRASUS on the TOP of Wyrmrest Temple in Dragonblight (59.8, 54.4). Follow his dialogue and delivery to your contact in ORIGINAL Northrend Dalaran: Arcanist Tybalin near the Alliance emblem vendors (39.6, 57.4), or Magister Hathorel inside the Horde inn, The Filthy Animal (69.8, 31.4). Legion Dalaran is the wrong city.",
    "Accept The Sunreaver Plan (Alliance) or The Silver Covenant's Scheme (Horde), then enter Dalaran's Underbelly. Alliance: kill the hostile SUNREAVER Agent in the northeastern Black Market (about 63, 15). Horde: kill the hostile SILVER COVENANT Agent at the southwestern Cantrips & Crows bar (about 35.6, 56.8). LOOT the Orders, deal with the exit ambusher, and return to your own contact upstairs. The friendly agent for the opposite quest cannot supply your Orders.",
    "For A Suitable Disguise, find Shandy Glossgleam on The Threads of Fate's UPSTAIRS BALCONY, around Dalaran 43, 48; the shop entrance is near 43, 50. Speak to him to begin the laundry task. Click the shirts, pants, unmentionables/delicates or water bucket exactly as he calls for them. After the successful sequence, LOOT the sack beside the tub for the Borrowed Tabard, then return to your contact. It is not automatically put into your bags.",
    "Use the Borrowed Tabard disguise BEFORE entering the opposing faction's quarter. Alliance: complete A Meeting With The Magister by speaking to Hathorel inside The Filthy Animal. Horde: complete An Audience With The Arcanist by speaking to Tybalin near the Alliance emblem vendors. Obtain Ancient Dragonforged Blades, return to your own contact, then follow Return To Caladis Brightspear / Myralion Sunblaze back to Quel'Delar's Rest. Finish the conversation/scene and accept Reforging The Sword.",
    "Enter NORMAL Pit of Saron from the Frozen Halls terrace in southern Icecrown (52.6, 89.4). With Reforging The Sword active, collect FIVE Infused Saronite Bars from the ground, kill Forgemaster Garfrost and loot the Forgemaster's Hammer. USE the hammer at Garfrost's anvil, around the eastern forge (68, 55), to make Reforged Quel'Delar. Return to your faction's quest NPC and take Tempering The Blade. If the dungeon route is locked, follow Jaina/Sylvanas's Frozen Halls introduction through the preceding dungeon first.",
    "Enter the Forge of Souls and defeat Bronjahm and the Devourer of Souls. At the Crucible of Souls just beyond the Devourer's platform (northern end of the instance), USE Reforged Quel'Delar to temper it. Return for the next quest, The Halls Of Reflection. Killing the bosses without using the quest item does not temper the blade.",
    "Enter the Halls of Reflection with Tempered Quel'Delar. Approach Frostmourne's pedestal at Sword's Rest in the first chamber; your blade animates and attacks. Personally tag it, defeat it and LOOT Subdued Quel'Delar. Keep pets from killing it before you can tag it. Return to your quest NPC; completing all ten dungeon waves and the Lich King escape is not required for this sword objective.",
    "Accept Journey To The Sunwell and travel to the LEGACY Isle of Quel'Danas, reachable through Shattrath's island portal at 48.9, 42.1. Speak to Halduron Brightwing OUTSIDE Sunwell Plateau at 44.4, 45.4. Use this original island and its quest phase; the ordinary raid portal does not take you directly to the purification scene.",
    "For Thalorien Dawnseeker, go south along the island's Dead Scar to Thalorien's Remains, about 53, 80 OUTDOORS. Interact with the remains, stay for the defense event and defeat the arriving Scourge until Thalorien grants his blessing. Return to Halduron; do not search inside the Sunwell raid for these remains.",
    "Accept The Purification of Quel'Delar, then speak to a WARDEN OF THE SUNWELL beside Halduron and choose the quest-entry teleport. In the special Sunwell scene, immerse the supplied Tempered Quel'Delar in the well, let the entire scene finish, and LOOT the restored blade before leaving. Return outside and finish the hand-in. Entering the normal raid or leaving before looting the sword does not finish this quest.",
    "Complete the final A Victory For The Silver Covenant / Sunreavers quest actually offered to your class: sword users are directed to Vereesa Windrunner / Archmage Aethas Sunreaver at Dalaran's Violet Citadel, while the alternative weapon branch sends you to Justicar Mariel Trueheart at the Argent Tournament. Follow that quest's named recipient, choose a reward and complete the hand-in for achievement credit. Classes that receive a mace can still earn The Sword in the Skull; the title does not require equipping a sword.",
},{pin(118,52.6,89.4,1,"Frozen Halls - Battered Hilt farming entrance"),pin(118,74.2,31.2,2,"Alliance - Caladis Brightspear"),pin(118,74.4,31.2,2,"Horde - Myralion Sunblaze"),pin(115,59.8,54.4,3,"Krasus - Wyrmrest Temple TOP floor"),pin(125,39.6,57.4,3,"Alliance contact - Arcanist Tybalin"),pin(125,69.8,31.4,3,"Horde contact - Magister Hathorel"),pin(126,63,15,4,"Alliance objective - hostile Sunreaver Agent / Black Market"),pin(126,35.6,56.8,4,"Horde objective - hostile Silver Covenant Agent / Cantrips & Crows"),pin(125,43,48,5,"Shandy Glossgleam - upstairs laundry balcony"),pin(125,69.8,31.4,6,"Alliance disguise objective - Hathorel in Horde inn"),pin(125,39.6,57.4,6,"Horde disguise objective - Tybalin in Alliance quarter"),pin(118,74.3,31.2,6,"Quel'Delar's Rest - return the book"),pin(118,52.6,89.4,7,"Frozen Halls - Pit of Saron entrance"),pin(184,68,55.3,7,"Garfrost's forge - hammer / anvil after collecting five bars"),pin(118,52.6,89.4,8,"Frozen Halls - Forge of Souls entrance"),pin(183,43.4,12,8,"Devourer of Souls - Crucible of Souls beyond platform"),pin(118,52.6,89.4,9,"Frozen Halls - Halls of Reflection entrance"),pin(111,48.9,42.1,10,"Shattrath portal - original Isle of Quel'Danas"),pin(122,44.4,45.4,10,"Halduron Brightwing - legacy island outside raid"),pin(122,53,80,11,"Thalorien's Remains - outdoor Dead Scar event"),pin(122,44.4,45.4,12,"Warden of the Sunwell - QUEST teleport"),pin(336,46,61.7,12,"Sunwell - immerse blade and loot it after the quest scene"),pin(125,31,48.6,13,"Violet Citadel - offered sword-branch turn-in"),pin(118,69.6,22.8,13,"Mariel Trueheart - offered alternative weapon turn-in")},"Keep the whole chain on the hilt recipient: dungeon quest items, phase access and final hand-ins belong to that character. Normal dungeon quest progress and recent Normal Pit of Saron hilt drops remain separate from the revamped Mythic dungeon.",{2594016,"https://www.wowhead.com/quest=24556#comments:id=911098","https://www.wowhead.com/quest=20438#comments:id=919425","https://www.wowhead.com/quest=14457#comments:id=919339","https://www.wowhead.com/quest=24557#comments:id=1051028","https://www.wowhead.com/quest=24461#comments","https://www.wowhead.com/quest=24476#comments","https://www.wowhead.com/quest=24480#comments:id=2195596","https://www.wowhead.com/quest=24553#comments:id=910859","https://www.wowhead.com/item=50379#comments:id=6438618","https://www.wowhead.com/item=50380#comments:id=6173182"})
